    384'h00000000000000000d1c0000000000000000000000000000000000000e8c000000000000000000000000000000000000,
    384'h0f440000000000000000000000000000000000000003d200000000000000000000000000000000000001e90000000000,
    384'h0000000000000000000000000000f4000000000000000000000000000000000000007a00000000000000000000000000,
    384'h0000000000023d000000000000000000000000000000000000011e000000000000000000000000000000000000028f00,
    384'h00000000000000000000000000000000000295000000000000000000000000000000000000034a000000000000000000,
    384'h00000000000000000003a500000000000000000000000000000000000000005940000000000000000000000000000000,
    384'h000000ac8000000000000000000000000000000000000056400000000000000000000000000000000000002b00000000,
    384'h00000000000000000000000000000095800000000000000000000000000000000000004ac00000000000000000000000,
    384'h000000000000002540000000000000000000000000000000000000cbc000000000000000000000000000000000000065,
    384'hc0000000000000000000000000000000000000b2c0000000000000000000000000000000000000000380000000000000,
    384'h00000000000000000000000021c000000000000000000000000000000000000030e00000000000000000000000000000,
    384'h0000000038700000000000000000000000000000000000003c300000000000000000000000000000000000003e100000,
    384'h000000000000000000000000000000003f000000000000000000000000000000000000001c0000000000000000000000,
    384'h00000000000000000e000000000000000000000000000000000000000700000000000000000000000000000000000000,
    384'h0007200000000000000000000000000000000000000b9000000000000000000000000000000000000005c80000000000,
    384'h0000000000000000000000000002e4000000000000000000000000000000000000017000000000000000000000000000,
    384'h000000000008b80000000000000000000000000000000000000c5c000000000000000000000000000000000000090c00,
    384'h00000000000000000000000000000000000c840000000000000000000000000000000000000e40000000000000000000,
    384'h000000000000000000000200000000000000000000000000000000000000010000000000000000000000000000000000,
    384'h000000800000000000000000000000000000000000000040000000000000000000000000000000000000002000000000,
    384'h000000000000000000000000000000100000000000000000000000000000000000000008000000000000000000000000,
    384'h000000000000000400000000000000000000000000000000000000020000000000000000000000000000000000000001};
  // M_SCW: 150 rows of 150 bits
  localparam logic [22499:0] M_SCW = {
    228'h964000000000000000000000000000000000012c00000000000000000,
    384'h000000000000000000a58000000000000000000000000000000000014b00000000000000000000000000000000000294,
    384'h0000000000000000000000000000000000252000000000000000000000000000000000004a4000000000000000000000,
    384'h00000000000002cd0000000000000000000000000000000000059800000000000000000000000000000000000b300000,
    384'h000000000000000000000000000000003be00000000000000000000000000000000000f7c00000000000000000000000,
    384'h000000000001ef000000000000000000000000000000000003dc000000000000000000000000000000000027b0000000,
    384'h00000000000000000000000000004f4000000000000000000000000000000000009e0000000000000000000000000000,
    384'h00000007c400000000000000000000000000000000002f800000000000000000000000000000000000df000000000000,
    384'h000000000000000000000000003380000000000000000000000000000000000267000000000000000000000000000000,
    384'h00000ccc0000000000000000000000000000000000399000000000000000000000000000000000007300000000000000,
    384'h0000000000000000000002e6000000000000000000000000000000000005cc0000000000000000000000000000000000,
    384'h27700000000000000000000000000000000000cec000000000000000000000000000000000019d000000000000000000,
    384'h00000000000000000003ee00000000000000000000000000000000000fdc00000000000000000000000000000000003f,
    384'hb000000000000000000000000000000000007f400000000000000000000000000000000000fe00000000000000000000,
    384'h0000000000000009fc000000000000000000000000000000000013f00000000000000000000000000000000000dc4000,
    384'h00000000000000000000000000000003b800000000000000000000000000000000000f70000000000000000000000000,
    384'h000000000000094c00000000000000000000000000000000003290000000000000000000000000000000000065000000,
    384'h000000000000000000000000000000ca0000000000000000000000000000000000099400000000000000000000000000,
    384'h0000000033200000000000000000000000000000000000664000000000000000000000000000000000029f0000000000,
    384'h000000000000000000000000053c00000000000000000000000000000000000a70000000000000000000000000000000,
    384'h000000082000000000000000000000000000000000001040000000000000000000000000000000000220000000000000,
    384'h000000000000000000000004400000000000000000000000000000000000088000000000000000000000000000000000,
    384'h0091000000000000000000000000000000000001220000000000000000000000000000000000004c0000000000000000,
    384'h000000000000000000209000000000000000000000000000000000004100000000000000000000000000000000000000,
    384'hd2000000000000000000000000000000000003a400000000000000000000000000000000000748000000000000000000,
    384'h00000000000000000e9000000000000000000000000000000000001d0000000000000000000000000000000000003a00,
    384'h000000000000000000000000000000000874000000000000000000000000000000000024600000000000000000000000,
    384'h00000000000048c000000000000000000000000000000000029100000000000000000000000000000000000002e80000,
    384'h0000000000000000000000000000000dd000000000000000000000000000000000001ba0000000000000000000000000,
    384'h0000000000b74000000000000000000000000000000000016e00000000000000000000000000000000000adc00000000,
    384'h0000000000000000000000000035b00000000000000000000000000000000000d1400000000000000000000000000000,
    384'h000003a2000000000000000000000000000000000007440000000000000000000000000000000000000ef40000000000,
    384'h0000000000000000000000001de00000000000000000000000000000000000bbc0000000000000000000000000000000,
    384'h00017700000000000000000000000000000000000aec000000000000000000000000000000000015d000000000000000,
    384'h000000000000000000002b800000000000000000000000000000000001ea00000000000000000000000000000000000b,
    384'hd4000000000000000000000000000000000037a000000000000000000000000000000000000020e00000000000000000,
    384'h000000000000000000c1c000000000000000000000000000000000038300000000000000000000000000000000000f04,
    384'h00000000000000000000000000000000003e0000000000000000000000000000000000007c0000000000000000000000,
    384'h00000000000000f8000000000000000000000000000000000001c8000000000000000000000000000000000003900000,
    384'h000000000000000000000000000000070000000000000000000000000000000000000047400000000000000000000000,
    384'h0000000000008e0000000000000000000000000000000000091c00000000000000000000000000000000003230000000,
    384'h0000000000000000000000000000e4400000000000000000000000000000000003c80000000000000000000000000000,
    384'h0000000f9000000000000000000000000000000000000ef000000000000000000000000000000000001dc00000000000,
    384'h0000000000000000000000023b00000000000000000000000000000000000003eb000000000000000000000000000000,
    384'h000007d400000000000000000000000000000000002fa00000000000000000000000000000000000df40000000000000,
    384'h0000000000000000000001be00000000000000000000000000000000000b7c0000000000000000000000000000000000,
    384'h16f00000000000000000000000000000000000d7000000000000000000000000000000000003ae000000000000000000,
    384'h00000000000000000f5c0000000000000000000000000000000000000448000000000000000000000000000000000008,
    384'h900000000000000000000000000000000000110000000000000000000000000000000000002200000000000000000000,
    384'h000000000000000044000000000000000000000000000000000020800000000000000000000000000000000000c10000,
    384'h000000000000000000000000000000009000000000000000000000000000000000000120000000000000000000000000,
    384'h000000000022400000000000000000000000000000000000003960000000000000000000000000000000000072c00000,
    384'h000000000000000000000000000000e5000000000000000000000000000000000009c800000000000000000000000000,
    384'h0000000013900000000000000000000000000000000000270000000000000000000000000000000000024e0000000000,
    384'h00000000000000000000000002c400000000000000000000000000000000002580000000000000000000000000000000,
    384'h0000cb0000000000000000000000000000000000000060000000000000000000000000000000000000c0000000000000,
    384'h000000000000000000000001800000000000000000000000000000000000030000000000000000000000000000000000,
    384'h00060000000000000000000000000000000000020c00000000000000000000000000000000000c180000000000000000,
    384'h000000000000000000003000000000000000000000000000000000008040000000000000000000000000000000000300};
  // ---- END GENERATED TABLES

  // the tables as nets: event-driven simulators index a net much faster
  // than a long parameter; synthesis sees the same constants
  wire [185999:0] m_enc   = M_ENC;
  wire [95999:0]  m_encl  = M_ENCL;
  wire [185999:0] m_syn   = M_SYN;
  wire [51199:0]  m_lam   = M_LAM;
  wire [51199:0]  m_le    = M_LE;
  wire [51199:0]  m_lo    = M_LO;
  wire [47999:0]  m_w     = M_W;
  wire [25599:0]  m_upl   = M_UPL;
  wire [22499:0]  m_upw   = M_UPW;
  wire [25599:0]  m_scl   = M_SCL;
  wire [22499:0]  m_scw   = M_SCW;

  // a * b in GF(2^10)
  function automatic logic [9:0] gmul(input logic [9:0] a, input logic [9:0] b);
    logic [9:0] p, x;
    p = '0;
    x = a;
    for (int i = 0; i < 10; i++) begin
      p = p ^ (x & {10{b[i]}});
      x = {x[8:0], 1'b0} ^ {6'd0, x[9], 2'd0, x[9]};
    end
    gmul = p;
  endfunction
  // a 10 x 10 GF(2) matrix times x (the powers of two of x are linear)
  function automatic logic [9:0] lin10(input logic [9:0] x, input logic [99:0] m);
    logic [9:0] y;
    for (int o = 0; o < 10; o++) y[o] = ^(x & m[10*o +: 10]);
    lin10 = y;
  endfunction
  // 1 / a = a^1022 (0 for a = 0), Itoh-Tsujii: a^(2^k - 1) for k = 2, 4, 8, 9
  function automatic logic [9:0] ginv(input logic [9:0] a);
    logic [9:0] b2, b4, b8, b9;
    b2 = gmul(lin10(a, M_SQ1), a);           // a^3
    b4 = gmul(lin10(b2, M_SQ2), b2);         // a^15
    b8 = gmul(lin10(b4, M_SQ4), b4);         // a^255
    b9 = gmul(lin10(b8, M_SQ1), a);          // a^511
    ginv = lin10(b9, M_SQ1);
  endfunction

  // The multiplications by constants are linear maps over GF(2): output bit
  // o is the XOR of the input bits row o of the map's table selects. The
  // datapath functions are computed in the clocked blocks, under the enables
  // that use them (the same logic as separate combinational blocks, and much
  // faster to simulate).

  // ======================================================================
  // encoder
  // ======================================================================
  logic [4:0]   eb;                          // beat number of the next input
  logic [299:0] epar;                        // remainder, x^j at [10j +: 10]
  wire          ece = !e_out_valid || e_out_ready;
  wire  [4:0]   ebn = e_in_first ? 5'd0 : eb;
  assign e_in_ready = ece;

  always_ff @(posedge clk or negedge rst_n)
    if (!rst_n) begin
      eb <= '0; epar <= '0;
      e_out_valid <= 1'b0; e_out_first <= 1'b0; e_out_data <= '0; ev_eresync <= 1'b0;
    end else begin
      ev_eresync <= e_in_valid && ece && e_in_first && eb != 5'd0;
      if (ece) begin
        e_out_valid <= e_in_valid;
        if (e_in_valid) begin : b_enc
          logic [299:0] r, np;
          logic [319:0] o;
          r = (ebn == 5'd0) ? '0 : epar;
          o = e_in_data;
          if (ebn == 5'd16) begin            // r x^2 + (m0 x + m1) x^30
            for (int j = 0; j < 300; j++) np[j] = ^({e_in_data[19:0], r} & m_encl[320*j +: 320]);
            for (int k = 2; k < P; k++) o[10*k +: 10] = np[10*(31-k) +: 10];   // parity, x^29 first
          end else                           // r x^32 + (sum m_k x^(31-k)) x^30
            for (int j = 0; j < 300; j++) np[j] = ^({e_in_data, r} & m_enc[620*j +: 620]);
          epar        <= np;
          e_out_data  <= o;
          e_out_first <= ebn == 5'd0;
          eb          <= (ebn == 5'd16) ? 5'd0 : ebn + 5'd1;
        end
      end
    end

  // ======================================================================
  // decoder
  //  input:   syndromes S_j = S_j a^32j + sum_k c_k a^j(31-k), the beat to
  //           the buffer
  //  riBM:    d[0..45] (d[46] = 0), theta[0..45], k, gamma, two iterations
  //           per clock; Lambda = d[15..30], Omega = d[0..14]
  //  pass 1:  r_i = lambda_i X^-i for symbol 0 of the beat, times a^ik for
  //           symbol k, times a^32i for the next beat; roots counted
  //  pass 2:  the same for Lambda (even and odd terms) and X^-30 Omega;
  //           e = X^-30 Omega / (X^-1 Lambda') at the roots
  //  output:  the beat read from the buffer plus e
  // ======================================================================
  wire          dce  = !d_out_valid || d_out_ready;
  wire          dacc = d_in_valid && dce;
  assign d_in_ready = dce;
  logic [4:0]   db;                          // beat number of the next input
  wire  [4:0]   dbn = d_in_first ? 5'd0 : db;
  logic [1:0]   wsl;                         // buffer slot being written
  logic [299:0] syn;
  logic [319:0] mem [0:127];                 // 4 codewords: {slot, beat}

  typedef enum logic [1:0] {BM_IDLE, BM_RUN, BM_DONE} bm_t;
  bm_t               bst;
  logic [3:0]        bcnt;
  logic [459:0]      bd, bth;
  logic signed [4:0] bk;                     // k / 2 (k is even after two iterations)
  logic [9:0]        bg;
  logic [1:0]        bsl;                    // slot of the codeword
  logic              bsnz;                   // its syndrome is not zero
  wire               bload = dacc && dbn == 5'd16;

  typedef enum logic {C_IDLE, C_RUN} ch_t;
  ch_t          p1st, p2st;
  logic [4:0]   p1b, p2b;
  logic [159:0] p1r, p1lam, p2l;
  logic [149:0] p1om, p2w;
  logic [3:0]   p1len, p1cnt;                // L, roots counted
  logic         p1long, p1snz;               // L > 15
  logic [1:0]   p1sl, p2sl;
  logic         p2fix, p2mark;
  wire          p1load = bst == BM_DONE;
  wire          p1last = p1st == C_RUN && p1b == 5'd16;
  wire          p2load = p1last;

  logic [319:0] rdq, eq;
  logic         v1, f1, m1;

  always_ff @(posedge clk)
    if (dacc) mem[{wsl, dbn}] <= d_in_data;

  always_ff @(posedge clk or negedge rst_n)
    if (!rst_n) begin
      db <= '0; wsl <= '0; syn <= '0;
      bst <= BM_IDLE; bcnt <= '0; bd <= '0; bth <= '0; bk <= '0; bg <= '0; bsl <= '0; bsnz <= 1'b0;
      p1st <= C_IDLE; p1b <= '0; p1r <= '0; p1lam <= '0; p1om <= '0; p1len <= '0; p1cnt <= '0;
      p1long <= 1'b0; p1snz <= 1'b0; p1sl <= '0;
      p2st <= C_IDLE; p2b <= '0; p2l <= '0; p2w <= '0; p2fix <= 1'b0; p2mark <= 1'b0; p2sl <= '0;
      rdq <= '0; eq <= '0; v1 <= 1'b0; f1 <= 1'b0; m1 <= 1'b0;
      d_out_valid <= 1'b0; d_out_first <= 1'b0; d_out_bad <= 1'b0; d_out_data <= '0;
      st_nsym <= '0; ev_corr <= 1'b0; ev_uncorr <= 1'b0; ev_dresync <= 1'b0;
    end else begin
      ev_dresync <= dacc && d_in_first && db != 5'd0;
      ev_corr    <= 1'b0;
      ev_uncorr  <= 1'b0;
      if (dce) begin
        // ---- input, syndromes
        if (dacc) begin : b_syn
          logic [299:0] sn, so;
          so = (dbn == 5'd0) ? '0 : syn;
          for (int j = 0; j < 300; j++) sn[j] = ^({d_in_data, so} & m_syn[620*j +: 620]);
          syn <= sn;
          db  <= (dbn == 5'd16) ? 5'd0 : dbn + 5'd1;
          if (dbn == 5'd16) begin            // the codeword is in: riBM
            wsl <= wsl + 2'd1;
            bd  <= {10'd1, 150'd0, sn}; bth <= {10'd1, 150'd0, sn};
            bk  <= '0; bg <= 10'd1; bcnt <= '0; bst <= BM_RUN; bsl <= wsl; bsnz <= sn != '0;
          end
        end
        // ---- riBM
        if (!bload)
          case (bst)
            BM_RUN: begin : b_bm
              logic [469:0]      d;
              logic [459:0]      th, nd;
              logic [9:0]        d0, g;
              logic signed [5:0] k;
              d = {10'd0, bd}; th = bth; k = {bk, 1'b0}; g = bg;
              for (int it = 0; it < 2; it++) begin
                d0 = d[9:0];
                for (int i = 0; i < 46; i++)
                  nd[10*i +: 10] = gmul(g, d[10*(i+1) +: 10]) ^ gmul(d0, th[10*i +: 10]);
                if (d0 != 10'd0 && !k[5]) begin
                  th = d[469:10]; g = d0; k = -k - 6'sd1;
                end else k = k + 6'sd1;
                d = {10'd0, nd};
              end
              bd <= d[459:0]; bth <= th; bk <= k[5:1]; bg <= g; bcnt <= bcnt + 4'd1;
              if (bcnt == 4'd14) bst <= BM_DONE;
            end
            BM_DONE: bst <= BM_IDLE;
            default: ;
          endcase
        // ---- Chien pass 1: roots of Lambda (Lambda(0) != 0: at most 15)
        if (p1load) begin
          for (int j = 0; j < 160; j++) p1r[j] <= ^(bd[309:150] & m_scl[160*j +: 160]);
          p1lam <= bd[309:150]; p1om <= bd[149:0];
          p1len <= 4'(5'd15 - 5'(bk)); p1long <= bk[4]; p1cnt <= '0; p1b <= '0;
          p1st <= C_RUN; p1sl <= bsl; p1snz <= bsnz;
        end
        if (p1st == C_RUN) begin : b_p1
          logic [319:0] v;
          logic [3:0]   fin;
          logic         unc;
          for (int j = 0; j < 320; j++) v[j] = ^(p1r & m_lam[160*j +: 160]);
          fin = p1cnt;
          for (int k = 0; k < P; k++) if (v[10*k +: 10] == 10'd0) fin = fin + 4'd1;
          if (!p1load) begin
            for (int j = 0; j < 160; j++) p1r[j] <= ^(p1r & m_upl[160*j +: 160]);
            p1cnt <= fin; p1b <= p1b + 5'd1;
            if (p1last) p1st <= C_IDLE;
          end
          // ---- last beat: the codeword goes to pass 2
          if (p1last) begin
            unc = p1long || fin != p1len;
            for (int j = 0; j < 160; j++) p2l[j] <= ^(p1lam & m_scl[160*j +: 160]);
            for (int j = 0; j < 150; j++) p2w[j] <= ^(p1om & m_scw[150*j +: 150]);
            p2fix     <= !unc && !cfg_bypass_corr;
            p2mark    <= (cfg_bypass_corr ? p1snz : unc) && !cfg_bypass_ind;
            st_nsym   <= (!unc && !cfg_bypass_corr) ? p1len : 4'd0;
            ev_corr   <= !unc && !cfg_bypass_corr && p1len != 4'd0;
            ev_uncorr <= cfg_bypass_corr ? p1snz : unc;
            p2b <= '0; p2st <= C_RUN; p2sl <= p1sl;
          end
        end
        // ---- Chien pass 2, Forney; buffer read
        v1 <= p2st == C_RUN;
        if (p2st == C_RUN) begin : b_p2
          logic [319:0] le, lo, w, e;
          for (int j = 0; j < 320; j++) begin
            le[j] = ^(p2l & m_le[160*j +: 160]);
            lo[j] = ^(p2l & m_lo[160*j +: 160]);
            w[j]  = ^(p2w & m_w[150*j +: 150]);
          end
          for (int k = 0; k < P; k++)
            e[10*k +: 10] = (p2fix && le[10*k +: 10] == lo[10*k +: 10]) ?
                            gmul(w[10*k +: 10], ginv(lo[10*k +: 10])) : 10'd0;
          rdq <= mem[{p2sl, p2b}]; eq <= e; f1 <= p2b == 5'd0; m1 <= p2mark;
          if (!p2load) begin
            for (int j = 0; j < 160; j++) p2l[j] <= ^(p2l & m_upl[160*j +: 160]);
            for (int j = 0; j < 150; j++) p2w[j] <= ^(p2w & m_upw[150*j +: 150]);
            p2b <= p2b + 5'd1;
            if (p2b == 5'd16) p2st <= C_IDLE;
          end
        end
        // ---- output
        d_out_valid <= v1;
        if (v1) begin
          d_out_data <= rdq ^ eq; d_out_first <= f1; d_out_bad <= m1;
        end
      end
    end
endmodule
